const hash=(bytes:Uint8Array|string)=>createHash('sha256').update(bytes).digest('hex');
const ref='mqxdjvsyckzocokuikmx',host=`db.${ref}.supabase.co`;
type Captured={sql:string;values:unknown[]};
const state={configs:[]as Record<string,unknown>[],clients:[]as FakeClient[],queries:[]as Captured[],authorized:true,history:[]as Record<string,unknown>[],locked:true,badIdentity:false,authCommand:null as {fingerprint:string;state:string;response:unknown}|null,checkpoints:[]as unknown[],failCommit:false,rolesAllowed:true,rolesConfigured:false,authUsers:[]as Record<string,unknown>[],population:[]as Record<string,unknown>[],learningRows:[]as Record<string,unknown>[],readOnly:true,learningReadFails:false,loopRows:{}as Record<string,Record<string,unknown>[]>,loopOriginals:[]as Record<string,unknown>[],loopScope:true};
const effects={installed:null as {fingerprint:string;state:string;response:InstalledPopulationReceipt|null}|null,seedApplied:false,vault:new Map<string,{id:string;decrypted_secret:string}>(),apiLogin:false,workerLogin:false,failSql:'',runtimePasswordRefused:false};
let transaction: {installed:typeof effects.installed;seedApplied:boolean;vault:typeof effects.vault;apiLogin:boolean;workerLogin:boolean;authCommand:typeof state.authCommand;checkpoints:unknown[]}|null=null;
function transactionalQuery(sql:string,values:unknown[]):{rows:Record<string,unknown>[]} | undefined{
 if(effects.failSql&&sql.includes(effects.failSql))throw Error('Controlled native write failure');
 if(sql==='BEGIN'){transaction=structuredClone({installed:effects.installed,seedApplied:effects.seedApplied,vault:effects.vault,apiLogin:effects.apiLogin,workerLogin:effects.workerLogin,authCommand:state.authCommand,checkpoints:state.checkpoints});return{rows:[]};}
 if(sql==='COMMIT'){if(state.failCommit)throw Error('Commit acknowledgement lost');transaction=null;return{rows:[]};}
 if(sql==='ROLLBACK'){if(transaction){Object.assign(effects,{installed:transaction.installed,seedApplied:transaction.seedApplied,vault:transaction.vault,apiLogin:transaction.apiLogin,workerLogin:transaction.workerLogin});state.authCommand=transaction.authCommand;state.checkpoints=transaction.checkpoints;transaction=null;}return{rows:[]};}
 if(sql.includes('CUEVO_INSTALLED_SCHEMA_STORAGE'))return{rows:[{available:!effects.failSql.includes('schema-storage')}]};if(sql.includes('CUEVO_INSTALLED_POPULATION_RECEIPT'))return{rows:effects.installed?[effects.installed]:[]};
 if(sql.startsWith('-- Synthetic fixtures only.')){effects.seedApplied=true;return{rows:[]};}
 if(sql.includes('internal.begin_command')&&values[1]===installedPopulationCommand){effects.installed={fingerprint:String(values[2]),state:'IN_PROGRESS',response:null};return{rows:[{begin_command:{state:'NEW'}}]};}
 if(sql.includes('internal.finish_command')&&values[1]===installedPopulationCommand){effects.installed={fingerprint:String(values[2]),state:'COMPLETED',response:JSON.parse(String(values[3]))};return{rows:[]};}
 if(sql.includes('internal.append_audit')&&values[0]==='operator.synthetic_population.installed')return{rows:[{append_audit:'installed-audit'}]};
 if(sql.includes('vault.decrypted_secrets')){const entry=effects.vault.get(String(values[0]));return{rows:entry?[sql.includes('select id,')?entry:{decrypted_secret:entry.decrypted_secret}]:[]};}
 if(sql.includes('vault.create_secret')){const name=String(values[1]);if(effects.vault.has(name))throw Error('Duplicate native Vault secret');effects.vault.set(name,{id:'vault-'+effects.vault.size,decrypted_secret:String(values[0])});return{rows:[{create_secret:'vault'}]};}
 if(sql.includes('vault.update_secret')){const name=String(values[2]),entry=effects.vault.get(name);if(!entry||entry.id!==values[0])throw Error('Unknown Vault source');effects.vault.set(name,{...entry,decrypted_secret:String(values[1])});return{rows:[]};}
 if(sql.includes('CUEVO_RUNTIME_LOGINS'))return{rows:[{apiLogin:effects.apiLogin,workerLogin:effects.workerLogin}]};
 if(sql.toLowerCase().startsWith('alter role cuevo_api')){effects.apiLogin=true;state.rolesConfigured=true;return{rows:[]};}
 if(sql.toLowerCase().startsWith('alter role cuevo_worker')){effects.workerLogin=true;state.rolesConfigured=true;return{rows:[]};}
 return undefined;
}
class FakeClient extends EventEmitter{
 connection={stream:{encrypted:true,authorized:true,getProtocol:()=> 'TLSv1.3',getPeerCertificate:()=>({raw:Buffer.from('peer-certificate'),subjectaltname:`DNS:${host}`})}};
 constructor(private config:Record<string,unknown>){super();state.configs.push(config);state.clients.push(this);}
 async connect(){this.connection.stream.authorized=state.authorized;if(this.config.user!=='postgres'&&effects.runtimePasswordRefused)throw Error('Saved runtime password refused');}
 async query(query:string|{text:string},values:unknown[]=[]){const sql=typeof query==='string'?query:query.text;state.queries.push({sql,values});const transactional=transactionalQuery(sql,values);if(transactional)return transactional;if(sql.includes('CUEVO_RUNTIME_CREDENTIAL_IDENTITY'))return{rows:[{operator:this.config.user,role:this.config.user,database:'postgres',ssl:true}]};if(sql.includes('CUEVO_RUNTIME_RECOVERED_ROLES'))return{rows:[{allowed:state.rolesAllowed}]};if(sql.includes('CUEVO_LEARNING_LOOP_READ_ONLY'))return{rows:[{readOnly:state.readOnly,operator:'postgres',role:'postgres',database:'postgres'}]};if(sql.includes('CUEVO_LEARNING_LOOP_ORIGINAL')){if(state.learningReadFails)throw Error('private database read error');return{rows:state.loopOriginals.length?state.loopOriginals.filter(row=>row.school_id===values[0]&&row.actor_id===values[1]&&row.key===values[2]&&row.command===values[3]):state.learningRows};}if(sql.includes('CUEVO_LOOP_CURRENT_SCOPE'))return{rows:[{permitted:state.loopScope}]};const loopMarker=/CUEVO_LOOP_([A-Z_]+)/.exec(sql)?.[1];if(loopMarker){if(!(loopMarker in state.loopRows))throw Error('Unexpected fixed native read marker');const rows=state.loopRows[loopMarker];return{rows:loopMarker==='ORIGINAL_AUDIT'&&rows.length>1?rows.filter(row=>row.school_id===values[0]&&row.actor_id===values[1]&&row.action===values[2]&&row.entity_type===values[3]&&row.entity_id===values[4]&&(values[5]===null||row.request_id===values[5])):loopMarker==='ORIGINAL_OUTBOX'&&rows.length>1?rows.filter(row=>row.school_id===values[0]&&row.actor_id===values[1]&&row.type===values[2]&&row.entity_type===values[3]&&row.entity_id===values[4]&&row.deduplication_key===values[5]):rows};}if(sql.includes('CUEVO_RUNTIME_INITIAL_ROLES'))return{rows:[{allowed:state.rolesAllowed}]};if(sql.includes('CUEVO_RUNTIME_CONFIGURED_ROLES'))return{rows:[{apiLogin:state.rolesConfigured,workerLogin:state.rolesConfigured}]};if(sql.toLowerCase().startsWith('alter role')){state.rolesConfigured=true;return{rows:[]};}if(sql.includes(' from app.'))return{rows:state.population};if(sql.includes(' from auth.users'))return{rows:state.authUsers};if(sql==='COMMIT'&&state.failCommit)throw Error('Commit acknowledgement lost');if(sql.startsWith('select fingerprint,state,response'))return{rows:state.authCommand?[state.authCommand]:[]};if(sql.startsWith('select coalesce(max((metadata'))return{rows:[{batch:state.checkpoints.length?Math.max(...state.checkpoints.map(row=>(row as {batch:number}).batch)):0}]};if(sql.startsWith('select metadata from internal.audit_events'))return{rows:state.checkpoints.map(metadata=>({metadata}))};if(sql.includes('internal.begin_command')){state.authCommand??={fingerprint:String(values[2]),state:'IN_PROGRESS',response:null};return{rows:[{begin_command:{state:'NEW'}}]};}if(sql.includes('internal.append_audit')){state.checkpoints.push(JSON.parse(String(values[5])));return{rows:[{append_audit:'audit'}]};}if(sql.includes('internal.finish_command')){state.authCommand={fingerprint:String(values[2]),state:'COMPLETED',response:JSON.parse(String(values[3]))};return{rows:[]};}if(sql.includes('CUEVO_NATIVE_QUIESCENCE'))return{rows:[{quiescent:true}]};if(sql.includes('pg_try_advisory_lock'))return{rows:[{locked:state.locked}]};if(sql.includes('pg_advisory_unlock'))return{rows:[{released:true}]};if(sql.includes('session_user'))return{rows:[{operator:state.badIdentity?'cuevo_api':'postgres',database:'postgres',ssl:true,serverVersion:170011}]};if(sql.includes('to_regclass'))return{rows:[{historyPresent:state.history.length>0}]};if(sql.includes('schema_migrations'))return{rows:state.history};return{rows:[{historyPresent:false}]};}
 async end(){this.emit('end');}
}
Object.assign(globalThis,{nativeDatabaseTestClient:FakeClient,nativeRuntimePopulationCheck:()=>{if(state.authUsers.length!==133)throw Error('Missing fixedpopulation');return{schools:2,people:133,memberships:133};},nativeRuntimeRoleChecks:()=>({checks:{foundation:true,runtimeRoles:true,transportPrivate:state.rolesAllowed}})});
registerHooks({load(url,context,next){if(/\/node_modules\/pg\/(?:lib\/index\.js|esm\/index\.mjs)$/.test(url.replaceAll('\\','/')))return{format:'module',shortCircuit:true,source:'export const Client=globalThis.nativeDatabaseTestClient;export default{Client};'};if(url.endsWith('/hosted-reference-population.ts'))return{format:'module',shortCircuit:true,source:'export const validateHostedReferencePopulation=globalThis.nativeRuntimePopulationCheck;'};if(url.endsWith('/hosted-migration-database.ts'))return{format:'module',shortCircuit:true,source:transformSync(readFileSync(new URL(url),'utf8').replace("const loaded=await import('./hosted-migration-plan').then(module=>module.readCanonicalMigrationSources({repoRoot:input.repoRoot,sourceSha:execFileSync('git',['-C',input.repoRoot,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),treeSha:execFileSync('git',['-C',input.repoRoot,'rev-parse','HEAD^{tree}'],{encoding:'utf8'}).trim()})),versions=loaded.sources.map(row=>row.name.slice(0,14)).sort(),post=await observeStage({stageId:'remaining',expectedAfterVersions:versions});","const post=globalThis.nativeRuntimeRoleChecks();"),{loader:'ts',format:'esm'}).code};return next(url,context);}});
async function api(){const p=resolve(import.meta.dirname,'hosted-migration-database.ts');let m:Record<string,unknown>={};try{m=await import(pathToFileURL(p).href);}catch(e){if((e as NodeJS.ErrnoException).code!=='ERR_MODULE_NOT_FOUND')throw e;}assert.equal(typeof m.createHostedMigrationDatabase,'function');return m as typeof import('./hosted-migration-database');}
async function fixture(run:(input:{repoRoot:string;projectRef:string;databaseUrl:string;certificate:{path:string;sha256:string};password:string})=>Promise<void>){
 const root=await mkdtemp(join(tmpdir(),'cuevo-migration-database-'));try{await mkdir(join(root,'.local/hosted-release'),{recursive:true});await writeFile(join(root,'.gitignore'),'.local/\n');execFileSync('git',['init','--quiet',root],{stdio:'ignore',windowsHide:true});const path=join(root,'.local/hosted-release/ca.pem');await writeFile(path,'-----BEGIN CERTIFICATE-----\nprivate fixture certificate\n-----END CERTIFICATE-----\n',{mode:0o600});Object.assign(state,{configs:[],clients:[],queries:[],authorized:true,history:[],locked:true,badIdentity:false,authCommand:null,checkpoints:[],failCommit:false,authUsers:[],population:[]});Object.assign(effects,{installed:null,seedApplied:false,vault:new Map(),apiLogin:false,workerLogin:false,failSql:'',runtimePasswordRefused:false});transaction=null;await run({repoRoot:root,projectRef:ref,databaseUrl:`postgresql://postgres@${host}:5432/postgres?sslmode=verify-full`,certificate:{path,sha256:hash(await readFile(path))},password:'private-db-fixture-password'});}finally{await rm(root,{recursive:true,force:true});}}
test('native lock uses explicit TLS options and the exact operator without ambient URL options',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{const db=await createHostedMigrationDatabase(input);let entered=0;const receipt=await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async lease=>{entered++;assert.equal(lease.key,`${ref}:HOSTED_SCHEMA_MIGRATION`);const evidence=await db.observe();assert.equal(evidence.operator,'postgres');assert.equal(evidence.tls.kind,'PEER_VERIFIED');assert.equal(evidence.tls.host,host);assert.deepEqual(evidence.history,[]);});assert.deepEqual(receipt,{kind:'RELEASED'});assert.equal(entered,1);const config=state.configs[0];assert.equal(config.connectionString,undefined);assert.equal(config.host,host);assert.equal(config.user,'postgres');assert.equal((config.ssl as {rejectUnauthorized:boolean}).rejectUnauthorized,true);assert.equal(config.password,input.password);assert.equal(JSON.stringify(receipt).includes(input.password),false);assert.ok(state.queries.some(q=>q.sql.includes('pg_advisory_unlock')));});});
test('untrusted peer or wrong database operator refuses the callback and preserves fixed errors',async()=>{const{createHostedMigrationDatabase}=await api();for(const mode of['tls','identity']as const)await fixture(async input=>{state.authorized=mode!=='tls';state.badIdentity=mode==='identity';const db=await createHostedMigrationDatabase(input);let called=false;await assert.rejects(db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{called=true;}),/requires review; contents withheld/);assert.equal(called,false);});});
test('connection loss aborts admitted execution and cannot return a released lock receipt',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{const db=await createHostedMigrationDatabase(input);await assert.rejects(db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{state.clients[0].emit('error',new Error(input.password));assert.equal(db.signal.aborted,true);await assert.rejects(db.observe());}),/requires review; contents withheld/);});});
test('raw history preserves native statements and actual table presence without inventing source hashes',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{const db=await createHostedMigrationDatabase(input);state.history=[{version:'20261001000000',name:'fixture',statements:['begin','select 1','commit']}];await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{const read=await db.observe();assert.deepEqual(read.history,state.history);assert.equal(read.historyPresent,true);});assert.equal(state.queries.some(q=>/insert|update|delete|create|drop|truncate/i.test(q.sql)),false);});});
test('rebound endpoint, changed CA and injected metadata are refused before credentials are consumed',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{for(const value of[{...input,databaseUrl:input.databaseUrl+'&host=other.invalid'},{...input,databaseUrl:input.databaseUrl.replace(host,'other.invalid')},{...input,databaseUrl:input.databaseUrl.replace('5432','6543')},{...input,certificate:{...input.certificate,sha256:'0'.repeat(64)}}])await assert.rejects(createHostedMigrationDatabase(value));let reads=0;await assert.rejects(createHostedMigrationDatabase({...input,get password(){reads++;return input.password;}}));assert.equal(reads,0);assert.equal(state.configs.length,0);});});
test('an unawaited observation cannot return current lock evidence once release begins',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{const db=await createHostedMigrationDatabase(input);let observation:Promise<unknown>|undefined;await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{observation=db.observe().then(()=>({kind:'RETURNED'}),()=>({kind:'REFUSED'}));});assert.deepEqual(await observation,{kind:'REFUSED'});});});
test('ambient PostgreSQL startup configuration cannot enter native operator admission',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{for(const name of['PGOPTIONS','PGCLIENT_ENCODING','PGREPLICATION','PGSSLNEGOTIATION']){const prior=process.env[name];try{process.env[name]='private-ambient-option';await assert.rejects(createHostedMigrationDatabase(input));}finally{if(prior===undefined)delete process.env[name];else process.env[name]=prior;}}const db=await createHostedMigrationDatabase(input);process.env.PGOPTIONS='-c search_path=public';try{await assert.rejects(db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{throw Error('No callback');}));assert.equal(state.configs.length,0);}finally{delete process.env.PGOPTIONS;}});});

test('native seed and original completed receipt commit in one held transaction without nested BEGIN or COMMIT',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{await installSeedSources(input.repoRoot);const db=await createHostedMigrationDatabase(input);await assert.rejects(db.executeOriginalSyntheticSeed());await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{await db.executeOriginalSyntheticSeed();const receipt=await db.readInstalledPopulation();assert.equal(receipt.sourceSha,execFileSync('git',['-C',input.repoRoot,'rev-parse','HEAD'],{encoding:'utf8'}).trim());await assert.rejects(db.executeOriginalSyntheticSeed());});const seed=state.queries.filter(query=>query.sql.startsWith('-- Synthetic fixtures only.'));assert.equal(seed.length,1);assert.doesNotMatch(seed[0].sql,/\bbegin;|\bcommit;\s*$/i);assert.equal(state.queries.filter(query=>query.sql==='BEGIN').length,1);assert.equal(state.queries.filter(query=>query.sql==='COMMIT').length,1);assert.equal(effects.seedApplied,true);assert.equal(effects.installed?.state,'COMPLETED');assert.ok(state.queries.findIndex(query=>query.sql.includes('internal.finish_command'))<state.queries.findIndex(query=>query.sql==='COMMIT'));});});

async function installSeedSources(root:string){const repository=resolve(import.meta.dirname,'../..');await mkdir(join(root,'supabase/seed'),{recursive:true});for(const file of ['seed.sql','identities.json'])await writeFile(join(root,'supabase/seed',file),execFileSync('git',['-C',repository,'show','HEAD:supabase/seed/'+file]));execFileSync('git',['-C',root,'add','supabase/seed'],{stdio:'ignore'});execFileSync('git',['-C',root,'-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','--quiet','-m','Source locked seed and manifest'],{stdio:'ignore'});}

test('failed native seed receipt or commit rolls back population and original authoritative receipt together',async()=>{const{createHostedMigrationDatabase}=await api();for(const failure of ['internal.finish_command','COMMIT'])await fixture(async input=>{await installSeedSources(input.repoRoot);effects.failSql=failure;const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{await assert.rejects(db.executeOriginalSyntheticSeed());await assert.rejects(db.readInstalledPopulation());});assert.equal(effects.seedApplied,false);assert.equal(effects.installed,null);assert.ok(state.queries.some(query=>query.sql==='ROLLBACK'));});});

test('installed seed receipt requires exact completed fingerprint before returning original source',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{await installSeedSources(input.repoRoot);const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{await db.executeOriginalSyntheticSeed();const receipt=await db.readInstalledPopulation();assert.equal(effects.installed!.fingerprint,installedPopulationFingerprint(receipt));effects.installed!.state='IN_PROGRESS';await assert.rejects(db.readInstalledPopulation());effects.installed!.state='COMPLETED';effects.installed!.fingerprint='0'.repeat(64);await assert.rejects(db.readInstalledPopulation());});});});

async function installCompletedPopulation(root:string){await installSeedSources(root);const sourceSha=execFileSync('git',['-C',root,'rev-parse','HEAD'],{encoding:'utf8'}).trim(),treeSha=execFileSync('git',['-C',root,'rev-parse','HEAD^{tree}'],{encoding:'utf8'}).trim();const bytes=await readFile(join(root,'supabase/seed/identities.json'));const manifest=JSON.parse(bytes.toString())as{actors:{actorId:string;email:string}[]};const receipt={version:1 as const,purpose:'CUEVO_INSTALLED_SYNTHETIC_POPULATION' as const,projectRef:ref,sourceSha,treeSha,seedSha256:'7be612e9a30e916ec4b460a2ae14a2796cb3f4f542cbdec8f7db2f49c95d9903' as const,manifestSha256:hash(canonicalReleaseExecutionJson(manifest))};effects.installed={fingerprint:installedPopulationFingerprint(receipt),state:'COMPLETED',response:receipt};state.authUsers=manifest.actors.map(actor=>({id:actor.actorId,email:actor.email,emailConfirmedAt:'2026-10-01T00:00:00Z',synthetic:true,isAnonymous:false,deletedAt:null,bannedUntil:null}));state.rolesAllowed=true;}

test('private runtime Vault creation and both admitted logins commit together and resume returns original credentials without ALTER',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{await installCompletedPopulation(input.repoRoot);const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{const first=await db.prepareRuntimeCredentials();assert.match(first.api,/^[a-f0-9]{64}$/);assert.match(first.worker,/^[a-f0-9]{64}$/);assert.notEqual(first.api,first.worker);const alters=state.queries.filter(query=>query.sql.startsWith('alter role'));assert.equal(alters.length,2);assert.equal(effects.apiLogin,true);assert.equal(effects.workerLogin,true);const second=await db.prepareRuntimeCredentials();assert.deepEqual(second,first);assert.equal(state.queries.filter(query=>query.sql.startsWith('alter role')).length,2);assert.equal(effects.vault.size,1);assert.ok(state.queries.findIndex(query=>query.sql.includes('vault.create_secret'))<state.queries.findIndex(query=>query.sql==='COMMIT'));});});});

test('private runtime creation failure rolls back Vault and both role logins without returning new credentials',async()=>{const{createHostedMigrationDatabase}=await api();for(const failure of ['alter role cuevo_worker','COMMIT'])await fixture(async input=>{await installCompletedPopulation(input.repoRoot);effects.failSql=failure;const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{await assert.rejects(db.prepareRuntimeCredentials());});assert.equal(effects.vault.size,0);assert.equal(effects.apiLogin,false);assert.equal(effects.workerLogin,false);assert.ok(state.queries.some(query=>query.sql==='ROLLBACK'));});});

test('resumed runtime credentials require actual restricted TLS login and current role membership without another ALTER',async()=>{const{createHostedMigrationDatabase}=await api();for(const failure of ['password','membership'])await fixture(async input=>{await installCompletedPopulation(input.repoRoot);const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{const first=await db.prepareRuntimeCredentials();const alters=state.queries.filter(query=>query.sql.startsWith('alter role')).length;if(failure==='password')effects.runtimePasswordRefused=true;else state.rolesAllowed=false;await assert.rejects(db.prepareRuntimeCredentials());assert.equal(state.queries.filter(query=>query.sql.startsWith('alter role')).length,alters);assert.equal(effects.vault.size,1);if(failure==='password'){const clients=state.configs.filter(config=>config.user==='cuevo_api'||config.user==='cuevo_worker');assert.ok(clients.length>=2);for(const config of clients){assert.equal(config.host,host);assert.equal(config.database,'postgres');assert.equal((config.ssl as {rejectUnauthorized:boolean}).rejectUnauthorized,true);assert.ok(config.password===first.api||config.password===first.worker);}}});});});

test('recovered membership NULL or a foreign grant never becomes allowed through shared SQL ownership',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{await installCompletedPopulation(input.repoRoot);const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{await db.prepareRuntimeCredentials();const alters=state.queries.filter(query=>query.sql.startsWith('alter role')).length,client=state.clients[0],original=client.query.bind(client);for(const allowed of [null,false]){client.query=async(query,values=[])=>{const sql=typeof query==='string'?query:query.text;return sql.includes('CUEVO_RUNTIME_RECOVERED_ROLES')?{rows:[{allowed}]}:original(query,values);};await assert.rejects(db.prepareRuntimeCredentials());assert.equal(state.queries.filter(query=>query.sql.startsWith('alter role')).length,alters);}client.query=original;});});});

