test('completed installed migration receipt accepts consecutive canonical Git appends and refuses reordered truncated or forged next source',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{
 await installSeedSources(input.repoRoot);await mkdir(join(input.repoRoot,'supabase/migrations'),{recursive:true});
 const required=['20261002021129_student_asset_storage_policies.sql','20261002021737_native_academic_source_identity.sql','20261002021206_curriculum_context_lifecycle.sql','20261002204500_posthog_environment_claim.sql','20261002195537_posthog_intelligence_observability.sql'];
 const repository=resolve(import.meta.dirname,'../..'),cutoff=execFileSync('git',['-C',repository,'ls-tree','-r','--name-only','HEAD','--','supabase/migrations'],{encoding:'utf8'}).split('\n').find(file=>file.includes('20261002021129_'))!;required[0]=cutoff.split('/').at(-1)!;
 const base=required.map(name=>({name,bytes:execFileSync('git',['-C',repository,'show','HEAD:supabase/migrations/'+name])}));for(const row of base)await writeFile(join(input.repoRoot,'supabase/migrations',row.name),row.bytes);
 const appended=['20261007130000_first_fixture.sql','20261007130100_second_fixture.sql'].map((name,index)=>({name,bytes:Buffer.from(`begin; select ${index+1}; commit;\n`)}));
 const git=(...args:string[])=>execFileSync('git',['-C',input.repoRoot,...args],{encoding:'utf8',stdio:'pipe'}).trim();
 const commit=()=>{git('add','.');git('-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','--quiet','-m','Append completed native migration');};
 const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{
  let prior:InstalledMigrationReceipt|null=null;
  for(let count=1;count<=3;count++){
   if(count>1)await writeFile(join(input.repoRoot,'supabase/migrations',appended[count-2].name),appended[count-2].bytes);commit();
   const sources=[...base,...appended.slice(0,count-1)],replay=replayPlan(sources),ordered=[...replay.before,replay.prerequisite,...replay.remaining];
   state.history=ordered.map(name=>{const row=sources.find(row=>row.name===name)!;return{version:name.slice(0,14),name:name.slice(15,-4),statements:[row.bytes.toString().trim()]};});
   const next:InstalledMigrationReceipt={version:1,purpose:'CUEVO_COMPLETED_INSTALLED_MIGRATIONS',projectRef:ref,sourceSha:git('rev-parse','HEAD'),treeSha:git('rev-parse','HEAD^{tree}'),migrationCount:sources.length,migrations:ordered.map(name=>({version:name.slice(0,14),sha256:hash(sources.find(row=>row.name===name)!.bytes)}))};
   try{await db.persistInstalledMigrations(next);}catch(error){throw new Error(`Completed migration fixture failed at append ${count}; last query ${state.queries.at(-1)?.sql}`,{cause:error});}assert.deepEqual(await db.readInstalledMigrations(),next);
   if(count===3){for(const bad of [{...next,migrations:[...next.migrations].reverse()},{...next,migrationCount:2,migrations:next.migrations.slice(0,2)},{...next,treeSha:'0'.repeat(40)},{...next,migrations:next.migrations.map((row,index)=>index?row:{...row,sha256:'0'.repeat(64)})}]){await assert.rejects(db.persistInstalledMigrations(bad));assert.deepEqual(await db.readInstalledMigrations(),next);}}
   prior=next;
  }
  assert.equal(prior?.migrationCount,7);
  const finalSource={name:'20261007130200_failed_receipt_append.sql',bytes:Buffer.from('begin; select 4; commit;\n')};await writeFile(join(input.repoRoot,'supabase/migrations',finalSource.name),finalSource.bytes);commit();
  const failed:InstalledMigrationReceipt={...prior!,sourceSha:git('rev-parse','HEAD'),treeSha:git('rev-parse','HEAD^{tree}'),migrationCount:8,migrations:[...prior!.migrations,{version:finalSource.name.slice(0,14),sha256:hash(finalSource.bytes)}]};state.history.push({version:finalSource.name.slice(0,14),name:finalSource.name.slice(15,-4),statements:[finalSource.bytes.toString().trim()]});effects.failSql='COMMIT';await assert.rejects(db.persistInstalledMigrations(failed));effects.failSql='';assert.deepEqual(await db.readInstalledMigrations(),prior);
 });
});});

test('partial native schema receipt commits exact staged history and resumes its metadata without population or whole-source completion',async()=>{const{createHostedMigrationDatabase}=await api();await fixture(async input=>{
 const repository=resolve(import.meta.dirname,'../..'),paths=execFileSync('git',['-C',repository,'ls-tree','-r','--name-only','HEAD','--','supabase/migrations'],{encoding:'utf8'}).trim().split('\n');const cutoff=paths.find(path=>path.includes('20261002021129_'))!;
 const names=[cutoff.split('/').at(-1)!,'20261002021737_native_academic_source_identity.sql','20261002021206_curriculum_context_lifecycle.sql','20261002204500_posthog_environment_claim.sql','20261002195537_posthog_intelligence_observability.sql'],sources=names.map(name=>({name,bytes:execFileSync('git',['-C',repository,'show','HEAD:supabase/migrations/'+name])}));
 await mkdir(join(input.repoRoot,'supabase/migrations'),{recursive:true});for(const source of sources)await writeFile(join(input.repoRoot,'supabase/migrations',source.name),source.bytes);await writeFile(join(input.repoRoot,'.gitattributes'),'supabase/migrations/* -text\n');
 const git=(...args:string[])=>execFileSync('git',['-C',input.repoRoot,...args],{encoding:'utf8',stdio:'pipe'}).trim();git('add','.');git('-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','--quiet','-m','Original schema stage source');
 const replay=replayPlan(sources),order=[...replay.before,replay.prerequisite,...replay.remaining],config='project_id = "cuevo"\n\n[db]\nmajor_version = 17\n\n[db.migrations]\nenabled = true\n\n[db.seed]\nenabled = false\n';
 const make=(count:number,stageId:'prefix'|'native'):InstalledSchemaReceipt=>{const included=order.slice(0,count).map(name=>({name,version:name.slice(0,14),sha256:hash(sources.find(row=>row.name===name)!.bytes)}));return{version:1,purpose:'CUEVO_INSTALLED_SCHEMA_STAGE',projectRef:ref,sourceSha:git('rev-parse','HEAD'),treeSha:git('rev-parse','HEAD^{tree}'),migrationCount:count,migrations:included.map(({version,sha256})=>({version,sha256})),stageId,stageSha256:hash(JSON.stringify({included,configSha256:hash(config)}))};};
 const db=await createHostedMigrationDatabase(input);await db.withLock(`${ref}:HOSTED_SCHEMA_MIGRATION`,async()=>{
  const prefix=make(replay.before.length,'prefix');state.history=order.slice(0,prefix.migrationCount).map(name=>({version:name.slice(0,14),name:name.slice(15,-4),statements:[sources.find(row=>row.name===name)!.bytes.toString().trim()]}));await db.persistInstalledSchema(prefix);assert.deepEqual(await db.readInstalledSchema(),prefix);assert.equal(await db.readInstalledMigrations(),null);await assert.rejects(db.readInstalledPopulation());
  const next=make(prefix.migrationCount+1,'native');state.history.push({version:replay.prerequisite.slice(0,14),name:replay.prerequisite.slice(15,-4),statements:[sources.find(row=>row.name===replay.prerequisite)!.bytes.toString().trim()]});effects.failSql='COMMIT';await assert.rejects(db.persistInstalledSchema(next));effects.failSql='';assert.deepEqual(await db.readInstalledSchema(),prefix);await db.persistInstalledSchema(next);assert.deepEqual(await db.readInstalledSchema(),next);
  for(const forged of [{...next,stageId:'prefix' as const},{...next,stageSha256:'0'.repeat(64)},{...next,migrations:[...next.migrations].reverse()},prefix])await assert.rejects(db.persistInstalledSchema(forged));
 });
});});

